"""Generate a browser QA surface from shipped app builders, using a isolated test drive."""
from pathlib import Path
import re
R=Path(__file__).resolve().parents[1];s=(R/'app.js').read_text()
def function(name):
 a=re.search(r'^  (?:async )?function '+name+r'\(',s,re.M).start();b=s.index('\n  }',a)+4;return s[a:b]
prefix=r'''
// QA only: memory storage and an isolated virtual drive; no account access.
const values=new Map(),localMemory={get length(){return values.size},key:i=>[...values.keys()][i],getItem:k=>values.get(k)||null,setItem:(k,v)=>values.set(k,String(v)),removeItem:k=>values.delete(k)};Object.defineProperty(window,'localStorage',{value:localMemory});
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),state={terminalCounter:0,bootedAt:Date.now(),windows:new Map(),user:{name:'Alex',borderStyle:'ring',borderColor:'#8fc6ff'},preferences:{desktopHidden:[]},theme:'blue',wallpaper:{type:'preset',value:'aurora'}},themes={blue:['#65a7ff','#8f7cff'],mint:['#5ee7c4','#4da6ff'],sunset:['#ff9b73','#b276ff']},wallpapers={aurora:'linear-gradient(145deg,#14335a,#28204a)'},nodes=new Map(),data=new Map();
const clean=p=>{const a=[];for(const v of String(p).split('/')){if(v==='..')a.pop();else if(v&&v!=='.')a.push(v)}return '/'+a.join('/')};
for(const p of ['/','/home','/home/user','/home/user/Documents','/home/user/Downloads','/home/user/Pictures'])nodes.set(p,{type:'dir'});
const PocketDisk={cleanPath:clean,parent:p=>clean(p).split('/').slice(0,-1).join('/')||'/',nameOf:p=>p.split('/').at(-1),getNode:async p=>nodes.get(p)||null,snapshot:async()=>Object.fromEntries(nodes),ensureDir:async p=>nodes.set(p,{type:'dir'}),writeText:async(p,t,mime='text/plain')=>{nodes.set(p,{type:'file',mime,size:new Blob([t]).size});data.set(p,t);dispatchEvent(new CustomEvent('pocketdiskchange',{detail:{path:p}}))},readText:async p=>data.get(p),readBlob:async p=>new Blob([data.get(p)]),isTextMime:m=>m?.startsWith('text/')||m==='application/json',mimeFromName:p=>p.endsWith('.png')?'image/png':'text/plain',formatBytes:n=>n+' B',stats:async()=>({used:[...data.values()].join('').length,max:1073741824,free:1073741824,persisted:false}),destroy:async()=>{nodes.clear();data.clear()}};window.PocketDisk=PocketDisk;PocketDisk.writeText('/home/user/Documents/Welcome.txt','Hello from the existing virtual drive.');
const saveJSON=(k,v)=>localMemory.setItem(k,JSON.stringify(v)),refreshFS=async()=>{},applyPreferences=()=>{},initDesktopGrid=()=>{},notify=()=>{},applyWallpaper=()=>{},setAuthWallpaper=()=>{},paintAvatar=el=>el.textContent='A',applyTheme=t=>{state.theme=t;document.documentElement.style.setProperty('--accent',themes[t][0]);},renderUserChrome=()=>{for(const w of state.windows.values())w.term?.updatePrompt();};let tutorialForNewProfile=false;
'''
# Exercise the production IndexedDB adapter in a separate test database.
storage=(R/'storage.js').read_text().replace("const DB_NAME = 'pocketvm-drive';", "const DB_NAME = 'pocketvm-desktop-qa-v129';")
(R/'tests/desktop-storage-under-test.js').write_text('// QA: only the database name differs from production.\n'+storage)
prefix=prefix[:prefix.index('const clean=')]+"const PocketDisk=window.PocketDisk;const ready=PocketDisk.init().then(async()=>{if(!await PocketDisk.getNode('/home/user/Documents/Welcome.txt'))await PocketDisk.writeText('/home/user/Documents/Welcome.txt','Hello from the existing virtual drive.');});\n"+prefix[prefix.index('const saveJSON='):]
body='\n'.join(function(n) for n in ['shellUser','buildTerminal','buildSettings','virtualDesktopInfo','buildAbout','openTutorial'])
suffix=r'''
const host=document.getElementById('qa-content'),win={id:'qa',el:document.getElementById('qa-window'),content:host};state.windows.set(win.id,win);
function openApp(id){win.cleanup?.();delete win.cleanup;delete win.term;if(id==='terminal')buildTerminal(win);else if(id==='settings')buildSettings(win);else if(id==='about')buildAbout(win);else host.textContent='Open Files from the real desktop to browse user files.';document.getElementById('qa-title').textContent=id==='settings'?'Settings':id==='about'?'About PocketVM':'Terminal';}
document.querySelectorAll('[data-qa-view]').forEach(b=>b.onclick=()=>openApp(b.dataset.qaView));document.getElementById('qa-tour').onclick=openTutorial;document.getElementById('qa-username').onchange=e=>{state.user.name=e.target.value;renderUserChrome()};ready.then(()=>openApp('terminal'));
'''
(R/'tests/desktop-under-test.js').write_text(prefix+body+suffix)
(R/'tests/desktop-qa.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PocketVM · isolated desktop QA</title><link rel="stylesheet" href="../styles.css?v=131"><style>body{background:radial-gradient(at 30% 20%,#28466c,#0a1324);height:100dvh;display:flex;flex-direction:column}.qa-header{display:flex;align-items:center;gap:7px;padding:9px 14px;flex-wrap:wrap;flex-shrink:0;background:#0a1324d9}.qa-header button{min-height:44px;font:12px system-ui;background:#ffffff0b;border:1px solid #ffffff25;border-radius:8px;padding:8px 13px;color:#dceaff}.qa-header span{font-size:10px;color:#abc1e0;margin-right:auto}.qa-header label{font:10px system-ui}.qa-header input{width:90px;background:#ffffff0a;color:white;border:1px solid #ffffff30;border-radius:7px;padding:7px;font:16px system-ui;min-height:44px}.qa-window{position:relative!important;inset:auto!important;transform:none!important;flex:1;min-height:0;width:calc(100% - 28px)!important;height:auto!important;margin:12px 14px}.qa-window .window-content{height:calc(100% - 40px)}.qa-window .titlebar{height:40px;min-height:40px}#desktop{position:relative;flex:1;min-height:0;display:flex;flex-direction:column}</style></head><body><header class="qa-header"><span>Isolated QA · isolated test drive</span><button data-qa-view="terminal">Terminal</button><button data-qa-view="settings">Settings</button><button data-qa-view="about">About</button><button id="qa-tour">Welcome tour</button><label>Profile <input id="qa-username" value="Alex" aria-label="QA profile name"></label></header><main id="desktop"><section id="qa-window" class="window focused qa-window"><header class="titlebar"><div class="window-title"><span class="window-icon">PV</span><span id="qa-title" class="window-name">Terminal</span></div></header><div id="qa-content" class="window-content"></div></section></main><script src="../terminal.js?v=131"></script><script src="../welcome.js?v=131"></script><script src="desktop-storage-under-test.js?v=131"></script><script src="desktop-under-test.js?v=131"></script></body></html>''')
(R/'tests/desktop-touch-layout.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>PocketVM · responsive desktop QA</title><style>body{font:14px system-ui;background:#dce6ec;color:#234158;margin:20px}header{display:flex;gap:18px;align-items:center}h1{font-size:18px}select{padding:12px}#stage{margin-top:20px;border:2px solid #34566f;width:1024px;height:768px}iframe{display:block;width:100%;height:100%;border:0}</style></head><body><header><h1>Desktop · responsive verification</h1><label>Viewport <select id="viewport"><option value="1024,768">iPad landscape</option><option value="768,1024">iPad portrait</option><option value="1366,1024">iPad Pro landscape</option><option value="507,768">iPad split view</option><option value="390,844">Phone portrait</option><option value="740,390">Phone landscape</option></select></label></header><p>Real shipped modules and extracted app builders. No user profile or persistent drive is accessed.</p><div id="stage"><iframe id="desktop-frame" title="PocketVM responsive QA" src="desktop-qa.html?v=131"></iframe></div><script>document.getElementById('viewport').onchange=e=>{const[w,h]=e.target.value.split(',');document.getElementById('stage').style.width=w+'px';document.getElementById('stage').style.height=h+'px'}</script></body></html>''')
print('Generated isolated QA from actual app builders.')
